import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        print(-1)
        return

    n = int(data[0])
    if n == 0 or n == 1:
        print(-1)
        return

    arr = list(map(int, data[1:n+1]))

    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] < arr[j]:
                count += 1

    if count == 0:
        print(-1)
    else:
        print(count)

if __name__ == "__main__":
    main()
